const pdfBase='https://heaths-app-hub.heath-tolley.chatgpt.site/watchmen/';
const dates=['2026-10-08','2026-10-07','2026-10-06','2026-10-05','2026-10-04','2026-10-03','2026-10-02','2026-09-30','2026-09-29','2026-09-28','2026-09-27','2026-09-26','2026-09-25','2026-09-24','2026-09-22','2026-09-21','2026-09-20','2026-09-19','2026-09-18','2026-09-17','2026-09-16','2026-09-15','2026-09-14','2026-09-13','2026-09-12','2026-09-11','2026-09-10','2026-09-09','2026-09-08'];
const monthNames=['January','February','March','April','May','June','July','August','September','October','November','December'];
const pretty=d=>{const [y,m,day]=d.split('-').map(Number);return monthNames[m-1]+' '+day+', '+y};
function render(){const q=document.getElementById('search').value.trim().toLowerCase();const rows=dates.filter(d=>pretty(d).toLowerCase().includes(q));document.getElementById('report-count').textContent=rows.length+' '+(rows.length===1?'report':'reports')+' · newest first';document.getElementById('reports-list').innerHTML=rows.length?rows.map(d=>'<article class="report"><div><time datetime="'+d+'">'+pretty(d)+'</time><h3>Watchmen on the Wall — Daily Watch</h3></div><a href="'+pdfBase+'Watchmen-on-the-Wall-'+d+'.pdf" target="_blank" rel="noopener">Open report ↗</a></article>').join(''):'<p class="empty">No reports match that date.</p>';}
document.getElementById('search').addEventListener('input',render);render();
